const defaults=()=>({version:1,theme:'evjf',name:'Nuestra despedida de soltera en Puglia',people:6,start:'',days:3,arrival:'Bari',budget:400,pace:'slow',transport:'driving',interests:['beach','food','party'],zone:null,plan:[],members:Array.from({length:6},(_,i)=>'Persona '+(i+1)),expenses:[],notes:[],splitLink:''});
