function validate(s){const safeId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x);if(!s||s.version!==1||!themes.some(t=>t[0]===s.theme)||typeof s.name!=='string'||s.name.length>80||!Number.isInteger(s.people)||s.people<2||s.people>40||!Number.isInteger(s.days)||s.days<1||s.days>14||!Array.isArray(s.plan)||s.plan.length>14||!Array.isArray(s.members)||s.members.length!==s.people||s.members.some(x=>typeof x!=='string'||!x.trim()||x.length>60)||new Set(s.members).size!==s.people)throw Error('Copia no reconocida');if(typeof s.start!=='string'||(s.start&&!/^\d{4}-\d{2}-\d{2}$/.test(s.start))||!['Bari','Brindisi','Foggia','Libre'].includes(s.arrival)||!['slow','active'].includes(s.pace)||!['driving','transit'].includes(s.transport)||!Number.isFinite(s.budget)||s.budget<0||s.budget>100000||!Array.isArray(s.interests)||s.interests.some(x=>!kinds[x])||!Array.isArray(s.expenses)||!Array.isArray(s.notes)||s.notes.length>1000||s.expenses.length>2000)throw Error('Datos no válidos');for(const d of s.plan){if(!Array.isArray(d)||d.length>50)throw Error('Programa no válido');for(const p of d){if(!safeId(p.uid)||typeof p.name!=='string'||p.name.length>200||typeof p.desc!=='string'||p.desc.length>4000||typeof p.time!=='string'||(p.lat!=null&&(!Number.isFinite(p.lat)||Math.abs(p.lat)>90))||(p.lon!=null&&(!Number.isFinite(p.lon)||Math.abs(p.lon)>180)))throw Error('Parada no válida')}}for(const e of s.expenses){if(!safeId(e.id)||typeof e.title!=='string'||!Number.isInteger(e.cents)||e.cents<1||e.cents>10000000||!s.members.includes(e.payer)||!Array.isArray(e.who)||!e.who.length||e.who.some(n=>!s.members.includes(n))||new Set(e.who).size!==e.who.length)throw Error('Gasto no válido')}for(const n of s.notes){if(!safeId(n.id)||typeof n.text!=='string'||n.text.length>4000||!['private','group'].includes(n.privacy)||!Number.isInteger(n.day)||n.day< -1||n.day>=s.days)throw Error('Nota no válida')}if(s.splitLink&&!validSplit(s.splitLink))throw Error('Enlace de grupo no válido');return s}
try{const saved=localStorage.getItem('aracne-puglia-v1');if(saved)state=validate(JSON.parse(saved))}catch{setTimeout(()=>toast('No se pudo cargar la copia local. Podéis importar una copia.'),400)}
function save(){try{localStorage.setItem('aracne-puglia-v1',JSON.stringify(state))}catch{toast('Guardado local no disponible. Exportad vuestro viaje.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function show(v){view=v;$$('.view').forEach(e=>e.classList.toggle('active',e.id===v));$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='map')setTimeout(drawMap,40);if(v==='plan')renderPlan();if(v==='budget')renderBudget();if(v==='notes')renderNotes();window.scrollTo({top:0,behavior:'smooth'})}
function dialog(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$$('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();show('prepare')};
function fillForm(){$('#tripName').value=state.name;$('#people').value=state.people;$('#start').value=state.start;$('#start').min=today();$('#days').innerHTML=Array.from({length:14},(_,i)=>`<option value="${i+1}">${i+1} ${i?'días':'día'}</option>`).join('');$('#days').value=state.days;$('#arrival').value=state.arrival;$('#budgetTarget').value=state.budget;$('#pace').value=state.pace;$('#transport').value=state.transport;renderChoices()}
function renderChoices(){$('#themes').innerHTML=themes.map(t=>`<button type="button" class="theme ${state.theme===t[0]?'selected':''}" data-theme="${t[0]}" aria-pressed="${state.theme===t[0]}"><b aria-hidden="true">${t[1]}</b>${t[2]}</button>`).join('');$('#interests').innerHTML=Object.entries(kinds).map(([k,n])=>`<button type="button" class="chip ${state.interests.includes(k)?'selected':''}" data-interest="${k}" aria-pressed="${state.interests.includes(k)}">${n}</button>`).join('');$$('[data-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.theme;save();renderChoices()});$$('[data-interest]').forEach(b=>b.onclick=()=>{const k=b.dataset.interest;state.interests=state.interests.includes(k)?state.interests.filter(x=>x!==k):[...state.interests,k];save();renderChoices()})}
function syncForm(){const count=Number($('#people').value),duration=Number($('#days').value);if(state.expenses.length&&count!==state.people){toast('El grupo ya tiene gastos: mantened su tamaño para conservar las cuentas.');$('#people').value=state.people;return false}if(state.plan.length>duration&&state.plan.slice(duration).some(x=>x.length)){if(!confirm('Reducir la duración eliminará las paradas de los últimos días. ¿Continuar?'))return false}Object.assign(state,{name:$('#tripName').value.trim(),people:count,start:$('#start').value,days:duration,arrival:$('#arrival').value,budget:Number($('#budgetTarget').value)||0,pace:$('#pace').value,transport:$('#transport').value});while(state.members.length<count)state.members.push('Persona '+(state.members.length+1));state.members=state.members.slice(0,count);state.plan=state.plan.slice(0,duration);state.notes.forEach(n=>{if(n.day>=duration)n.day=-1});day=Math.min(day,duration-1);save();return true}
$('#tripForm').onsubmit=async e=>{e.preventDefault();if(!syncForm())return;if(!state.interests.length){toast('Elegid al menos un interés.');return}$('#recommendations').hidden=false;weatherByZone={};renderZones();$('#recommendations').scrollIntoView({behavior:'smooth',block:'start'});await weather()};
function score(z){let n=state.interests.filter(t=>z.tags.includes(t)).length*10;if(z.arrival===state.arrival)n+=state.days<4?10:4;if(['evjf','evg','friends'].includes(state.theme)&&['bari','salento'].includes(z.id)&&state.interests.includes('party'))n+=3;if(state.theme==='family'&&z.tags.includes('nature'))n+=3;const w=weatherByZone[z.id];if(w)n+=w.bonus;return n}
function renderZones(){const sorted=[...zones].sort((a,b)=>score(b)-score(a));$('#zoneCards').innerHTML=sorted.map((z,i)=>{const w=weatherByZone[z.id];return `<article class="zoneCard"><div><span class="eyebrow">${i===0?'NUESTRA PRIMERA PROPUESTA':esc(z.base)}</span><h3>${esc(z.name)}</h3><p>${esc(z.desc)}</p><span class="tag">${state.interests.filter(t=>z.tags.includes(t)).map(t=>kinds[t]).join(' · ')||'Otro ambiente por explorar'}</span>${w?`<p class="weather">${w.temp} °C máx. media · ${w.rain} % lluvia máx. · viento máx. ${w.wind} km/h<br>${w.count}/${state.days} días couverts · ${esc(z.base)} / punto representativo</p>`:''}</div><button class="primary" data-zone="${z.id}">Elegir esta zona</button></article>`}).join('');$$('[data-zone]').forEach(b=>b.onclick=()=>generate(b.dataset.zone))}
async function weather(){const seq=++weatherSequence;const diff=(new Date(state.start+'T00:00:00Z')-new Date(today()+'T00:00:00Z'))/86400000;const node=$('#weatherStatus');if(diff<0||diff>15){node.textContent='Fechas fuera del plazo de previsión. Las zonas se ordenan por intereses y llegada, sin ventajas meteorológicas supuestas. Comprobad la temporada de playas y locales; comparad el tiempo cerca de la salida.';return}node.textContent='Comparando el tiempo en las seis zonas…';try{const q=new URLSearchParams({latitude:zones.map(z=>z.lat).join(','),longitude:zones.map(z=>z.lon).join(','),daily:'temperature_2m_max,precipitation_probability_max,wind_speed_10m_max',timezone:'Europe/Rome',forecast_days:'16'});const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);let res;try{res=await fetch('https://api.open-meteo.com/v1/forecast?'+q,{signal:controller.signal})}finally{clearTimeout(timeout)}if(!res.ok)throw Error();const data=await res.json();if(seq!==weatherSequence)return;if(!Array.isArray(data)||data.length!==zones.length)throw Error();const result={};data.forEach((d,i)=>{const indexes=d.daily.time.map((t,j)=>({t,j})).filter(v=>v.t>=state.start&&v.t<dateAt(state.days));const valid=indexes.filter(({j})=>Number.isFinite(d.daily.temperature_2m_max[j])&&Number.isFinite(d.daily.precipitation_probability_max[j])&&Number.isFinite(d.daily.wind_speed_10m_max[j]));if(!valid.length)return;let temp=Math.round(valid.reduce((a,v)=>a+d.daily.temperature_2m_max[v.j],0)/valid.length),rain=Math.max(...valid.map(v=>d.daily.precipitation_probability_max[v.j])),wind=Math.round(Math.max(...valid.map(v=>d.daily.wind_speed_10m_max[v.j])));result[zones[i].id]={temp,rain,wind,count:valid.length,bonus:(100-rain)/15-Math.max(0,wind-20)/5+(state.interests.includes('beach')?Math.max(-5,5-Math.abs(temp-26)):0)}});weatherByZone=result;node.textContent=`Previsiones Open-Meteo consultadas a las ${new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}. Lluvia, viento y temperatura complementan vuestros intereses. ${diff+state.days>16?'El viaje supera el plazo de previsión: comparación parcial. ':''}Son puntos representativos, no una garantía para cada playa; comprobad el estado del mar.`;renderZones()}catch{if(seq===weatherSequence){weatherByZone={};node.textContent='Meteorología no disponible. La clasificación solo usa vuestros intereses y llegada; no se inventan previsiones.';renderZones()}}}
function dateAt(d){if(!state.start)return '';let dt=new Date(state.start+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+d);return dt.toISOString().slice(0,10)}
function dayLabel(d){const t=dateAt(d);return 'Día '+(d+1)+(t?' · '+new Date(t+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'}):'')}
function distance(a,b){const rad=x=>x*Math.PI/180;const x=rad(b.lat-a.lat),y=rad(b.lon-a.lon);return 6371*2*Math.asin(Math.sqrt(Math.sin(x/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(y/2)**2))}
function generate(zone){if(state.plan.some(d=>d.length)&&!confirm('¿Sustituir el programa por una nueva propuesta? Se conservarán las notas y los gastos.'))return;state.zone=zone;const z=zones.find(x=>x.id===zone);let pool=places.filter(p=>p.zone===zone&&p.name!=='Islas Tremiti').sort((a,b)=>b.tags.filter(t=>state.interests.includes(t)).length-a.tags.filter(t=>state.interests.includes(t)).length);const limit=state.pace==='slow'?2:3;state.plan=[];for(let d=0;d<state.days;d++){if(!pool.length){state.plan.push([{uid:uid(),name:'Día libre en '+z.base,desc:'Dejad tiempo para vuestras ideas o añadid una actividad desde el mapa.',time:'10:00',lat:null,lon:null}]);continue}let first=pool.shift(),chosen=[first];pool.sort((a,b)=>distance(first,a)-distance(first,b));while(chosen.length<limit&&pool.length&&distance(first,pool[0])<(state.transport==='transit'?25:65))chosen.push(pool.shift());state.plan.push(chosen.map((p,i)=>({...p,uid:uid(),time:['10:00','15:00','18:00'][i],desc:p.desc+(p.tags.includes('party')&&state.interests.includes('party')?' Para salir de noche, buscad un local abierto en vuestras fechas y organizad la vuelta.':'')})))}day=0;save();show('plan');toast('La primera propuesta está lista. Todo se puede modificar.')}
function allSteps(){return state.plan.flat()}
function renderPlan(){$('#planTitle').textContent=state.name;$('#planSummary').innerHTML=`<p>${state.people} personas · ${state.days} días · ${themes.find(t=>t[0]===state.theme)[2]}${state.zone?' · '+esc(zones.find(z=>z.id===state.zone)?.name||''):''}</p><p class="notice">${state.transport==='transit'?'Los horarios de autobuses y trenes no están verificados. Comprobad cada enlace antes de reservar.':'Horarios y tiempo libre propuestos: ajustadlos a las reservas y a los desplazamientos.'} ${state.budget?'Presupuesto objetivo: '+money(state.budget*100)+' / persona, sin estimación del precio de las actividades.':''}</p>`;$('#dayTabs').innerHTML=Array.from({length:state.days},(_,i)=>`<button class="${day===i?'active':''}" data-day="${i}">${esc(dayLabel(i))}</button>`).join('');$$('[data-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.day);renderPlan()});const arr=state.plan[day]||[];$('#itinerary').innerHTML=arr.length?arr.map((p,i)=>`<article class="step"><span class="number">${i+1}</span><div class="stepContent"><span class="eyebrow">${esc(p.time)||'HORARIO LIBRE'}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="actions"><button class="mini" data-edit="${esc(p.uid)}">Modificar</button><button class="mini" data-up="${i}" ${i===0?'disabled':''} aria-label="Subir ${esc(p.name)}">↑</button><button class="mini" data-down="${i}" ${i===arr.length-1?'disabled':''} aria-label="Bajar ${esc(p.name)}">↓</button><button class="mini" data-remove="${i}" aria-label="Quitar ${esc(p.name)}">Quitar</button>${Number.isFinite(p.lat)?`<a class="mini" href="${waze(p)}" target="_blank" rel="noopener">Waze</a>`:''}</div></div></article>`).join(''):'<div class="empty">Este día es vuestro.<br>Añadid lugares desde el mapa o una parada libre.</div>';$$('[data-edit]').forEach(b=>b.onclick=()=>editStep(b.dataset.edit));$$('[data-up]').forEach(b=>b.onclick=()=>move(Number(b.dataset.up),-1));$$('[data-down]').forEach(b=>b.onclick=()=>move(Number(b.dataset.down),1));$$('[data-remove]').forEach(b=>b.onclick=()=>{arr.splice(Number(b.dataset.remove),1);save();renderPlan()});const route=arr.filter(p=>Number.isFinite(p.lat));if(state.transport==='transit'&&route.length>1){$('#routeActions').innerHTML=route.slice(1).map((p,i)=>`<a class="secondary" href="${mapsUrl([route[i],p])}" target="_blank" rel="noopener">Conexión ${i+1} · Google Maps</a>`).join('');return}$('#routeActions').innerHTML=route.length?`<a class="primary" href="${mapsUrl(route)}" target="_blank" rel="noopener">Ruta del día · Google Maps</a>${route.length>5?'<p class="small">Se incluyen las cinco primeras paradas. Abrid las siguientes por separado.</p>':''}`:''}
function move(i,delta){const arr=state.plan[day];[arr[i],arr[i+delta]]=[arr[i+delta],arr[i]];save();renderPlan()}
function mapsUrl(arr){arr=arr.slice(0,5);const q=new URLSearchParams({api:'1',destination:arr.at(-1).lat+','+arr.at(-1).lon,travelmode:state.transport});if(arr.length>1)q.set('origin',arr[0].lat+','+arr[0].lon);if(arr.length>2&&state.transport!=='transit')q.set('waypoints',arr.slice(1,-1).map(p=>p.lat+','+p.lon).join('|'));return 'https://www.google.com/maps/dir/?'+q}
function waze(p){return 'https://www.waze.com/ul?'+new URLSearchParams({ll:p.lat+','+p.lon,navigate:'yes'})}
function editStep(id){const old=(state.plan[day]||[]).find(p=>p.uid===id);dialog(old?'Modificar la parada':'Una parada a vuestra medida',`<form id="stepForm"><label>Nombre<input id="stepName" maxlength="200" required value="${esc(old?.name||'')}"></label><div class="grid2"><label>Horario<input id="stepTime" type="time" value="${esc(old?.time||'10:00')}"></label><label>Día<select id="stepDay">${Array.from({length:state.days},(_,i)=>`<option value="${i}" ${i===day?'selected':''}>${esc(dayLabel(i))}</option>`).join('')}</select></label></div><label>Vuestra idea / dirección<textarea id="stepDesc" rows="3" maxlength="4000">${esc(old?.desc||'')}</textarea></label><div class="grid2"><label>Latitud (opcional)<input id="stepLat" type="number" step="any" min="-90" max="90" value="${old?.lat??''}"></label><label>Longitud (opcional)<input id="stepLon" type="number" step="any" min="-180" max="180" value="${old?.lon??''}"></label></div><p class="small">Sin coordenadas, la parada aparece en el programa pero no en el mapa.</p><button class="primary">Guardar la parada</button></form>`);$('#stepForm').onsubmit=e=>{e.preventDefault();if(Boolean($('#stepLat').value)!==Boolean($('#stepLon').value)){toast('Introducid ambas coordenadas o dejad ambas vacías.');return}const target=Number($('#stepDay').value);const p={...(old||{}),uid:old?.uid||uid(),name:$('#stepName').value.trim(),desc:$('#stepDesc').value,time:$('#stepTime').value,lat:$('#stepLat').value===''?null:Number($('#stepLat').value),lon:$('#stepLon').value===''?null:Number($('#stepLon').value)};if(old)state.plan[day]=state.plan[day].filter(x=>x.uid!==id);while(state.plan.length<state.days)state.plan.push([]);state.plan[target].push(p);day=target;save();$('#modal').close();renderPlan()}}
$('#addManual').onclick=()=>editStep();$('#explore').onclick=()=>show('map');
$('#zoneFilter').innerHTML+=zones.map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('');$('#zoneFilter').onchange=drawMap;$('#search').oninput=drawMap;
function filtered(){const q=$('#search').value.toLowerCase();return places.filter(p=>($('#zoneFilter').value==='all'||p.zone===$('#zoneFilter').value)&&[p.name,p.desc,...p.tags.map(t=>kinds[t])].join(' ').toLowerCase().includes(q))}
function drawMap(){const list=filtered();$('#placeCount').textContent=list.length+' lugares';$('#places').innerHTML=list.map(p=>`<article class="place"><span class="tag">${p.tags.slice(0,2).map(t=>kinds[t]).join(' · ')}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><button class="secondary" data-add="${p.id}">＋ Al programa</button></article>`).join('')||'<p>Ningún lugar coincide con la búsqueda.</p>';$$('[data-add]').forEach(b=>b.onclick=()=>choosePlace(b.dataset.add));if(!window.L){$('#mapFallback').textContent='Mapa no disponible. Todos los lugares siguen disponibles en la lista.';return}if(!map){$('#mapCanvas').innerHTML='';map=L.map('mapCanvas').setView([41,17],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);layer=L.layerGroup().addTo(map)}layer.clearLayers();list.forEach(p=>{const included=allSteps().some(s=>s.id===p.id);const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'',html:`<div class="pin ${included?'inplan':''}">${included?'✓':'•'}</div>`,iconSize:[27,27]})}).addTo(layer);const box=document.createElement('div');box.innerHTML=`<strong>${esc(p.name)}</strong><br>${esc(p.desc)}<br>`;const b=document.createElement('button');b.textContent='Añadir al programa';b.className='secondary';b.onclick=()=>choosePlace(p.id);box.append(b);marker.bindPopup(box)});const coords=(state.plan[day]||[]).filter(p=>Number.isFinite(p.lat)).map(p=>[p.lat,p.lon]);if(coords.length>1)L.polyline(coords,{color:'#e94057',weight:3,dashArray:'6 8'}).addTo(layer);map.invalidateSize();if(list.length)map.fitBounds(L.latLngBounds(list.map(p=>[p.lat,p.lon])),{padding:[25,25],maxZoom:11})}
function choosePlace(id){const p=places.find(p=>p.id===id);dialog(p.name,`<p>${esc(p.desc)}</p><label>¿A qué día añadirlo?<select id="addDay">${Array.from({length:state.days},(_,i)=>`<option value="${i}" ${i===day?'selected':''}>${esc(dayLabel(i))}</option>`).join('')}</select></label><button class="primary" id="confirmAdd">Añadir esta parada</button>`);$('#confirmAdd').onclick=()=>{day=Number($('#addDay').value);while(state.plan.length<state.days)state.plan.push([]);state.plan[day].push({...p,uid:uid(),time:''});save();$('#modal').close();drawMap();toast(p.name+' añadido al día '+(day+1))}}
function renderBudget(){const total=state.expenses.reduce((a,e)=>a+e.cents,0);$('#budgetSummary').innerHTML=`<div class="stat"><strong>${money(total)}</strong><span>Gastos registrados</span></div><div class="stat"><strong>${money(Math.round(total/state.people))}</strong><span>Media / persona</span></div><div class="stat"><strong>${state.people}</strong><span>En el grupo</span></div>`;$('#members').value=state.members.join(', ');$('#payer').innerHTML=state.members.map(n=>`<option>${esc(n)}</option>`).join('');$('#beneficiaries').innerHTML=state.members.map((n,i)=>`<label class="check"><input type="checkbox" value="${i}" checked>${esc(n)}</label>`).join('');$('#expenseList').innerHTML=state.expenses.map(e=>`<article class="expense"><div><strong>${esc(e.title)}</strong><p>${esc(e.payer)} pagó · repartido entre ${e.who.length} personas</p><button class="textBtn" data-delete-exp="${e.id}">Eliminar</button></div><strong>${money(e.cents)}</strong></article>`).join('');$$('[data-delete-exp]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este gasto?')){state.expenses=state.expenses.filter(e=>e.id!==b.dataset.deleteExp);save();renderBudget()}});const transfers=settle();$('#settlements').innerHTML=transfers.length?transfers.map(t=>`<div class="settle"><b>${esc(t.from)}</b> reembolsa <b>${money(t.cents)}</b> a ${esc(t.to)}</div>`).join(''):'<p>No hay reembolsos pendientes.</p>';$('#splitLink').value=state.splitLink;$('#openSplit').hidden=!state.splitLink;if(state.splitLink)$('#openSplit').href=state.splitLink}
function settle(){const balance=Object.fromEntries(state.members.map(n=>[n,0]));for(const e of state.expenses){balance[e.payer]+=e.cents;const each=Math.floor(e.cents/e.who.length),rest=e.cents%e.who.length;e.who.forEach((n,i)=>balance[n]-=each+(i<rest?1:0))}const debt=Object.entries(balance).filter(([,v])=>v<0).map(([n,v])=>({n,v:-v})),credit=Object.entries(balance).filter(([,v])=>v>0).map(([n,v])=>({n,v}));const out=[];let i=0,j=0;while(i<debt.length&&j<credit.length){const c=Math.min(debt[i].v,credit[j].v);out.push({from:debt[i].n,to:credit[j].n,cents:c});debt[i].v-=c;credit[j].v-=c;if(!debt[i].v)i++;if(!credit[j].v)j++}return out}
$('#saveMembers').onclick=()=>{const list=$('#members').value.split(',').map(x=>x.trim()).filter(Boolean);if(list.length!==state.people||new Set(list).size!==list.length||list.some(x=>x.length>60)){toast('Introducid exactamente '+state.people+' nombres diferentes (máximo 60 caracteres).');return}if(state.expenses.length&&state.members.some((n,i)=>list[i]!==n)){toast('Los nombres están vinculados a gastos. Eliminad o exportad los gastos antes de renombrar el grupo.');return}state.members=list;save();renderBudget();toast('Participantes guardados')};
$('#expenseForm').onsubmit=e=>{e.preventDefault();const who=$$('#beneficiaries input:checked').map(x=>state.members[Number(x.value)]);if(!who.length){toast('Elegid al menos un beneficiario.');return}state.expenses.push({id:uid(),title:$('#expenseTitle').value.trim(),cents:Math.round(Number($('#amount').value)*100),payer:$('#payer').value,who});save();$('#expenseForm').reset();renderBudget();toast('Gasto añadido')};
function validSplit(link){try{const u=new URL(link);return u.protocol==='https:'&&['splitwise.com','tricount.com','tricount.page.link','tricount.app'].some(d=>u.hostname===d||u.hostname.endsWith('.'+d))}catch{return false}}
$('#saveSplit').onclick=()=>{let l=$('#splitLink').value.trim();if(l&&!validSplit(l)){toast('Usad un enlace HTTPS oficial de Splitwise o Tricount.');return}state.splitLink=l;save();renderBudget();toast('Enlace guardado')};
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),15000)}
$('#exportExpenses').onclick=()=>{const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'"+'$&').replace(/"/g,'""')+'"';const rows=[['Gasto','Importe EUR','Pagado por','Beneficiarios'],...state.expenses.map(e=>[e.title,(e.cents/100).toFixed(2),e.payer,e.who.join(' | ')])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'aracne-depenses.csv')};
function renderNotes(){$('#noteDay').innerHTML='<option value="-1">Todo el viaje</option>'+Array.from({length:state.days},(_,i)=>`<option value="${i}">${esc(dayLabel(i))}</option>`).join('');$('#noteList').innerHTML=state.notes.map(n=>`<article class="noteCard"><div class="small">${n.privacy==='private'?'Personal':'Para el grupo'} · ${n.day<0?'Todo el viaje':esc(dayLabel(n.day))}</div><div>${esc(n.text)}</div><div class="actions"><button class="textBtn" data-edit-note="${n.id}">Modificar</button><button class="textBtn" data-delete-note="${n.id}">Eliminar</button></div></article>`).join('');$$('[data-delete-note]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar esta nota?')){state.notes=state.notes.filter(n=>n.id!==b.dataset.deleteNote);save();renderNotes()}});$$('[data-edit-note]').forEach(b=>b.onclick=()=>{const n=state.notes.find(n=>n.id===b.dataset.editNote);dialog('Modificar la nota',`<form id="editNoteForm"><label>Nota<textarea id="editNote" rows="5" required maxlength="4000">${esc(n.text)}</textarea></label><label>Visibilidad<select id="editPrivacy"><option value="private" ${n.privacy==='private'?'selected':''}>Personal</option><option value="group" ${n.privacy==='group'?'selected':''}>Para el grupo</option></select></label><button class="primary">Guardar</button></form>`);$('#editNoteForm').onsubmit=e=>{e.preventDefault();n.text=$('#editNote').value;n.privacy=$('#editPrivacy').value;save();$('#modal').close();renderNotes()}})}
$('#noteForm').onsubmit=e=>{e.preventDefault();state.notes.unshift({id:uid(),text:$('#noteText').value,day:Number($('#noteDay').value),privacy:$('#notePrivacy').value});save();$('#noteText').value='';renderNotes();toast('Nota guardada en el diario')};
function shareText(scope,includeNotes){const indexes=scope==='all'?Array.from({length:state.days},(_,i)=>i):[Number(scope)];let lines=[state.name,state.people+' personas · '+themes.find(t=>t[0]===state.theme)[2],''];for(const d of indexes){lines.push(dayLabel(d));const arr=state.plan[d]||[];arr.forEach(p=>lines.push((p.time?p.time+' · ':'')+p.name+(p.desc?' — '+p.desc:'')));if(!arr.length)lines.push('Programa libre');const route=arr.filter(p=>Number.isFinite(p.lat));if(state.transport==='transit'&&route.length>1)route.slice(1).forEach((p,i)=>lines.push('Conexión '+(i+1)+' : '+mapsUrl([route[i],p])));else if(route.length)lines.push('Itinerario'+(route.length>5?' (5 primeras paradas)':'')+' : '+mapsUrl(route));lines.push('')}if(includeNotes){const notes=state.notes.filter(n=>n.privacy==='group'&&(n.day===-1||indexes.includes(n.day)));if(notes.length)lines.push('Notas del grupo',...notes.map(n=>'• '+n.text))}lines.push('Preparado con Il Volo d’Aracne · Puglia');return lines.join('\n')}
function shareDialog(){dialog('Compartir el viaje',`<p>Enviad el programa completo o un solo día. Las notas personales y los gastos quedan excluidos.</p><label>¿Qué queréis compartir?<select id="shareScope"><option value="all">Todo el programa</option>${Array.from({length:state.days},(_,i)=>`<option value="${i}">${esc(dayLabel(i))}</option>`).join('')}</select></label><label class="check"><input id="includeNotes" type="checkbox">Incluir las notas « Para el grupo »</label><label>Vista previa<textarea id="sharePreview" rows="7" readonly></textarea></label><div class="actions"><a id="wa" class="primary" target="_blank" rel="noopener">WhatsApp</a><button id="nativeShare" class="secondary">Compartir…</button><button id="copyShare" class="textBtn">Copiar el texto</button></div><p class="small">Se comparte una copia del programa, no un espacio colaborativo sincronizado.</p>`);const update=()=>{const t=shareText($('#shareScope').value,$('#includeNotes').checked);$('#sharePreview').value=t;$('#wa').href='https://wa.me/?text='+encodeURIComponent(t)};$('#shareScope').onchange=update;$('#includeNotes').onchange=update;update();$('#nativeShare').onclick=async()=>{try{if(navigator.share)await navigator.share({title:state.name,text:$('#sharePreview').value});else await copy($('#sharePreview').value)}catch(e){if(e.name!=='AbortError')toast('No se puede compartir: copiad el texto o usad WhatsApp.')}};$('#copyShare').onclick=()=>copy($('#sharePreview').value)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Texto copiado')}catch{toast('Seleccionad el texto en la vista previa para copiarlo.')}}
$('#shareTop').onclick=shareDialog;$('#sharePlan').onclick=shareDialog;
$('#export').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'aracne-voyage.json');
$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error();const candidate=validate(JSON.parse(await f.text()));if(!confirm('¿Sustituir el borrador local por esta copia? Exportad primero el borrador si queréis conservarlo.'))return;state=candidate;day=0;weatherSequence++;weatherByZone={};$('#recommendations').hidden=true;save();fillForm();show('prepare');toast('Viaje importado')}catch{toast('Esta copia no es válida o es demasiado grande. Se ha conservado vuestro viaje.')}finally{e.target.value=''}};
$('#storyPhoto').onchange=e=>{const f=e.target.files[0];if(f&&f.size>15e6){toast('Elegid una foto de menos de 15 MB.');return}photoFile=f;$('#photoStatus').textContent=f?'Foto elegida: '+f.name:''};
function wrapText(ctx,text,x,y,maxWidth,lineHeight,maxLines=5){let words=text.split(/\s+/),line='',lines=[];for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines.slice(0,maxLines).forEach((l,i)=>ctx.fillText(l+(i===maxLines-1&&lines.length>maxLines?'…':''),x,y+i*lineHeight));return y+Math.min(lines.length,maxLines)*lineHeight}
$('#createStory').onclick=async()=>{try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const c=canvas.getContext('2d');const grad=c.createLinearGradient(0,0,1080,1920);grad.addColorStop(0,'#692676');grad.addColorStop(.55,'#e94057');grad.addColorStop(1,'#f27121');c.fillStyle=grad;c.fillRect(0,0,1080,1920);if(photoFile){const img=await createImageBitmap(photoFile);const s=Math.max(1080/img.width,1920/img.height);c.drawImage(img,(1080-img.width*s)/2,(1920-img.height*s)/2,img.width*s,img.height*s);img.close();c.fillStyle='#24132ca8';c.fillRect(0,0,1080,1920)}c.fillStyle='white';c.font='600 30px sans-serif';c.fillText('IL VOLO D’ARACNE',85,150);c.font='28px sans-serif';c.fillText('PUGLIA · INSIEME',85,205);c.font='700 72px sans-serif';let y=wrapText(c,state.name,85,440,900,85,3);c.font='32px sans-serif';c.fillText(state.people+' personas · '+dayLabel(day),85,y+35);y+=180;c.font='500 43px sans-serif';const arr=(state.plan[day]||[]).slice(0,3);if(!arr.length)c.fillText('Nuestros recuerdos empiezan aquí.',85,y);arr.forEach((p,i)=>{y=wrapText(c,(i+1)+'. '+p.name,85,y,880,60,2)+32});if((state.plan[day]||[]).length>3){c.font='28px sans-serif';c.fillText('Y más momentos por descubrir…',85,y+20)}c.font='28px sans-serif';c.fillText('Nuestra Puglia, a nuestra manera.',85,1735);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();const url=URL.createObjectURL(blob);dialog('Vuestra historia está lista',`<img src="${url}" alt="Vista previa de la historia"><div class="actions"><button class="primary" id="downloadStory">Descargar la imagen</button><button class="secondary" id="shareStory">Compartir la imagen</button></div><p class="small">Importad después la imagen en Instagram o Facebook. No se publica nada automáticamente.</p>`);$('#downloadStory').onclick=()=>download(blob,'aracne-story.png');$('#shareStory').onclick=async()=>{const f=new File([blob],'aracne-story.png',{type:'image/png'});try{if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:state.name});else{download(blob,'aracne-story.png');toast('Imagen descargada: abrid vuestra red social para importarla.')}}catch(e){if(e.name!=='AbortError')toast('Descargad la imagen para compartirla.')}};$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}catch{toast('No se puede leer la foto. Probad una imagen JPEG/PNG o cread la historia sin foto.')}};
